<script>
import doctorsData from '../data/doctors.json'
export default {
  name: 'Doctors',
  data: () => ({ doctors: doctorsData.doctors, searchQuery: '', selectedSpecialty: 'All' }),
  computed: {
    specialties() { return ['All', ...new Set(this.doctors.flatMap(doctor => doctor.specialties))] },
    filteredDoctors() { const query = this.searchQuery.trim().toLowerCase(); return this.doctors.filter(doctor => (this.selectedSpecialty === 'All' || doctor.specialties.includes(this.selectedSpecialty)) && (!query || [doctor.name, doctor.role, ...doctor.specialties].join(' ').toLowerCase().includes(query))) }
  },
  methods: { formatSpecialties(specialties) { return specialties.join(' & ') } }
}
</script>

<template><div class="doctors-v2">
  <section class="doctors-hero"><div class="site-container"><nav class="doctors-breadcrumb" aria-label="Breadcrumb"><router-link to="/">Home</router-link><i class="bi bi-chevron-right"></i><span>Our Doctors</span></nav><p class="eyebrow">Our medical team</p><h1>Meet the doctors behind your care</h1><p>Experienced specialists and compassionate clinicians working together to deliver exceptional care for every patient.</p></div></section>
  <section class="section doctors-directory"><div class="site-container"><div class="doctors-directory__heading"><div><p class="eyebrow">Find a specialist</p><h2>Our medical team</h2><p>Explore our doctors by specialty, or search for the care you need.</p></div><router-link to="/book-appointment" class="button-primary">Book appointment</router-link></div><div class="doctors-controls"><div class="doctors-filter" aria-label="Filter doctors by specialty"><button v-for="specialty in specialties" :key="specialty" type="button" :class="{active:selectedSpecialty===specialty}" @click="selectedSpecialty=specialty">{{ specialty }}</button></div><label class="doctors-search"><span class="visually-hidden">Search doctors</span><input v-model="searchQuery" type="search" placeholder="Search doctors or specialties"><i class="bi bi-search"></i></label></div><p class="doctors-count">{{ filteredDoctors.length }} doctor{{ filteredDoctors.length === 1 ? '' : 's' }} found</p><div v-if="filteredDoctors.length" class="doctors-grid"><router-link v-for="doctor in filteredDoctors" :key="doctor.id" :to="{name:'DoctorDetail',params:{id:doctor.id}}" class="doctor-tile"><img :src="doctor.image || 'https://placehold.co/640x520/e8f2f8/0b4f8a?text=BSH'" :alt="doctor.name"><div><p>{{ formatSpecialties(doctor.specialties) }}</p><h3>{{ doctor.name }}</h3><span>{{ doctor.role }}</span><strong>View profile <i class="bi bi-arrow-up-right"></i></strong></div></router-link></div><div v-else class="doctors-empty"><i class="bi bi-search"></i><h3>No doctors found</h3><p>Try another specialty or a different search term.</p></div></div></section>
  <section class="doctors-cta"><div class="site-container"><div><h2>Need help choosing a specialist?</h2><p>Call our team and we will help direct you to the right clinic.</p></div><a href="tel:+2347033449959" class="about-button-light"><i class="bi bi-telephone"></i>&nbsp; +234 703 344 9959</a></div></section>
</div></template>

